<script setup lang="ts">import {probability,logValue} from '../utils/format';defineProps<{inference:any}>()</script><template><section class="posterior-bars"><h2>{{inference.target}} · 两个状态的后验</h2><div v-for="p in inference.posterior" :key="p.state" class="posterior-row"><div><b>状态 {{p.state}}</b><strong>{{probability(p.probability,p.probability_underflow)}}</strong></div><div class="posterior-track"><i :style="{width:(p.probability*100)+'%'}"></i></div><small>log P = {{logValue(p.log_probability)}}</small></div><p class="method-note">归一分母logZ={{logValue(inference.log_evidence)}}；后验和{{inference.probability_sum.toFixed(12)}}。已观测目标先核对证据再返回one-hot。</p></section></template>
